var e=[{label:`订单已创建`,value:`CREATED`},{label:`下单成功`,value:`CREATE_SUCCESS`},{label:`下单失败`,value:`CREATE_FAILED`},{label:`交易成功`,value:`SUCCESS`},{label:`交易结束`,value:`FINISHED`},{label:`交易关闭`,value:`CLOSED`},{label:`未知通知状态`,value:`UNKNOWN_NOTIFY`}],t=[{label:`支付成功`,value:`TRADE_SUCCESS`},{label:`交易结束`,value:`TRADE_FINISHED`},{label:`交易关闭`,value:`TRADE_CLOSED`}],n={CREATED:`订单已创建`,CREATE_SUCCESS:`下单成功`,CREATE_FAILED:`下单失败`,SUCCESS:`交易成功`,FINISHED:`交易结束`,CLOSED:`交易关闭`,UNKNOWN_NOTIFY:`未知通知状态`},r={TRADE_SUCCESS:`支付成功`,TRADE_FINISHED:`交易结束`,TRADE_CLOSED:`交易关闭`},i={PROCESSING:`处理中`,SUCCESS:`退款成功`,FAILED:`退款失败`},a={SUCCESS:`处理成功`,FAIL:`处理失败`,FAILED:`处理失败`};function o(e,t){return t?e[t]||t:`-`}function s(e){return o(n,e)}function c(e){return o(r,e)}function l(e){return o(i,e)}function u(e){return o(a,e)}export{t as a,l as i,e as n,c as o,s as r,u as t};